'use strict';let currentImages=[];let currentLightboxIndex=0;function getVehicleIdFromURL(){const params=new URLSearchParams(window.location.search);return params.get('id');}function isValidVehicleId(id){if(!id||typeof id!=='string')return false;return/^[a-zA-Z0-9-]{1,20}$/.test(id);}async function fetchVehicleData(id){const response=await fetch('data/vehicles.json');if(!response.ok){throw new Error(`Failed to load vehicle data:${response.status}${response.statusText}`);}const vehicles=await response.json();return vehicles.find(v=>v.id===id)||null;}function escapeHtml(str){const div=document.createElement('div');div.textContent=String(str);return div.innerHTML;}function announce(message){const region=document.getElementById('sr-announce');if(!region)return;region.textContent='';setTimeout(()=>{region.textContent=message;},50);}function updateMetaTags(vehicle,title){document.title=`${title}|Premium Auto Sales`;const raw=vehicle.description||`${title}for sale at Premium Auto Sales.`;const description=raw.length>155?raw.slice(0,152)+'...':raw;const metaDesc=document.querySelector('meta[name="description"]');if(metaDesc)metaDesc.setAttribute('content',description);const ogTitle=document.getElementById('og-title');if(ogTitle)ogTitle.setAttribute('content',`${title}|Premium Auto Sales`);const ogDesc=document.getElementById('og-description');if(ogDesc)ogDesc.setAttribute('content',description);const ogImage=document.getElementById('og-image');if(ogImage&&vehicle.images&&vehicle.images.length>0){ogImage.setAttribute('content',vehicle.images[0]);}const ogUrl=document.getElementById('og-url');if(ogUrl)ogUrl.setAttribute('content',window.location.href);}function renderVehicleDetails(vehicle){const title=`${vehicle.year}${vehicle.make}${vehicle.model}`;const breadcrumbEl=document.getElementById('breadcrumb-vehicle');if(breadcrumbEl)breadcrumbEl.textContent=title;const titleEl=document.getElementById('vehicle-title');if(titleEl)titleEl.textContent=title;if(vehicle.images&&vehicle.images.length>0){const mainImg=document.getElementById('main-image');if(mainImg){mainImg.src=vehicle.images[0];mainImg.alt=`${title}— main photo`;}}const specMap={'spec-make':vehicle.make,'spec-model':vehicle.model,'spec-year':String(vehicle.year),'spec-price':`$${vehicle.price.toLocaleString()}`,'spec-mileage':`${vehicle.mileage.toLocaleString()}mi`,'spec-color':vehicle.color,'spec-transmission':vehicle.transmission,'spec-fuel-type':vehicle.fuelType,'spec-vin':vehicle.vin,'spec-condition':vehicle.condition,};for(const[id,value]of Object.entries(specMap)){const el=document.getElementById(id);if(el)el.textContent=value||'—';}const priceEl=document.getElementById('vehicle-price');if(priceEl)priceEl.textContent=`$${vehicle.price.toLocaleString()}`;const ctaEl=document.getElementById('contact-cta');if(ctaEl)ctaEl.href=`contact.html?vehicle_id=${encodeURIComponent(vehicle.id)}`;const featuresList=document.getElementById('features-list');if(featuresList&&vehicle.features&&vehicle.features.length>0){featuresList.innerHTML=vehicle.features .map(f=>`<li>${escapeHtml(f)}</li>`).join('');}const descEl=document.getElementById('vehicle-description');if(descEl)descEl.textContent=vehicle.description||'';updateMetaTags(vehicle,title);}function swapMainImage(index){if(index<0||index>=currentImages.length)return;const mainImg=document.getElementById('main-image');if(mainImg){mainImg.src=currentImages[index];mainImg.alt=`Vehicle photo ${index+1}of ${currentImages.length}`;}const thumbnails=document.querySelectorAll('.gallery-thumbnail');thumbnails.forEach((thumb,i)=>{const active=i===index;thumb.classList.toggle('active',active);thumb.setAttribute('aria-pressed',String(active));});announce(`Image ${index+1}of ${currentImages.length}`);}function initializeGallery(images){currentImages=images;const thumbnailStrip=document.getElementById('thumbnail-strip');if(!thumbnailStrip)return;thumbnailStrip.innerHTML=images.map((src,index)=>{const activeClass=index===0?' active':'';const lazyAttr=index<4?'eager':'lazy';return `<img src="${src}" alt="Vehicle photo ${index+1}" class="gallery-thumbnail${activeClass}" data-index="${index}" data-src="${src}" width="100" height="75" loading="${lazyAttr}" decoding="async" role="button" tabindex="0" aria-label="View photo ${index+1}" aria-pressed="${index===0}">`;}).join('');thumbnailStrip.addEventListener('click',(e)=>{const thumb=e.target.closest('.gallery-thumbnail');if(!thumb)return;swapMainImage(parseInt(thumb.dataset.index,10));});thumbnailStrip.addEventListener('keydown',(e)=>{const thumb=e.target.closest('.gallery-thumbnail');if(!thumb)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();swapMainImage(parseInt(thumb.dataset.index,10));}});const mainImg=document.getElementById('main-image');if(mainImg){mainImg.addEventListener('click',()=>{const activeThumb=thumbnailStrip.querySelector('.gallery-thumbnail.active');const activeIndex=activeThumb?parseInt(activeThumb.dataset.index,10):0;openLightbox(activeIndex);});}document.addEventListener('keydown',(e)=>{const lightbox=document.getElementById('lightbox');if(lightbox&&!lightbox.hidden)return;if(e.key==='ArrowLeft'){const activeThumb=thumbnailStrip.querySelector('.gallery-thumbnail.active');const idx=activeThumb?parseInt(activeThumb.dataset.index,10):0;if(idx>0)swapMainImage(idx-1);}else if(e.key==='ArrowRight'){const activeThumb=thumbnailStrip.querySelector('.gallery-thumbnail.active');const idx=activeThumb?parseInt(activeThumb.dataset.index,10):0;if(idx<images.length-1)swapMainImage(idx+1);}});}function updateLightboxImage(index){const img=document.getElementById('lightbox-image');const counter=document.getElementById('lightbox-counter');if(img){img.src=currentImages[index];img.alt=`Vehicle photo ${index+1}of ${currentImages.length}`;}if(counter){counter.textContent=`${index+1}/${currentImages.length}`;}announce(`Image ${index+1}of ${currentImages.length}`);}function openLightbox(imageIndex){currentLightboxIndex=imageIndex;const lightbox=document.getElementById('lightbox');if(!lightbox)return;updateLightboxImage(imageIndex);lightbox.hidden=false;const mainEl=document.getElementById('main');if(mainEl)mainEl.setAttribute('inert','');const closeBtn=document.getElementById('lightbox-close');if(closeBtn)closeBtn.focus();}function closeLightbox(){const lightbox=document.getElementById('lightbox');if(!lightbox)return;lightbox.hidden=true;const mainEl=document.getElementById('main');if(mainEl)mainEl.removeAttribute('inert');const mainImg=document.getElementById('main-image');if(mainImg)mainImg.focus();}function navigateLightbox(direction){const newIndex=currentLightboxIndex+direction;if(newIndex<0||newIndex>=currentImages.length)return;currentLightboxIndex=newIndex;updateLightboxImage(newIndex);}async function fetchRelatedVehicles(currentVehicle){try{const response=await fetch('data/vehicles.json');if(!response.ok)return[];const vehicles=await response.json();return vehicles .filter(v=>{if(v.id===currentVehicle.id)return false;const sameType=v.type===currentVehicle.type;const nearPrice=Math.abs(v.price-currentVehicle.price)<=5000;return sameType||nearPrice;}).slice(0,4);}catch{return[];}}function renderRelatedVehicles(vehicles){const grid=document.getElementById('related-vehicles');if(!grid)return;if(!vehicles||vehicles.length===0){const section=document.querySelector('.related-vehicles-section');if(section)section.hidden=true;return;}grid.innerHTML=vehicles.map(vehicle=>{const title=`${vehicle.year}${vehicle.make}${vehicle.model}`;const image=vehicle.images&&vehicle.images.length>0?vehicle.images[0]:'';return `<article class="inventory-card"><div class="inventory-card-image"><img src="${image}" alt="${escapeHtml(title)}" width="600" height="400" loading="lazy" decoding="async"></div><div class="inventory-card-content"><h3 class="inventory-card-title">${escapeHtml(title)}</h3><div class="inventory-card-info"><span>${escapeHtml(vehicle.type)}</span><span>${vehicle.mileage.toLocaleString()}mi</span><span>${escapeHtml(vehicle.color)}</span></div><p class="inventory-card-price">$${vehicle.price.toLocaleString()}</p><a href="vehicle-detail.html?id=${encodeURIComponent(vehicle.id)}" class="inventory-card-cta">View Details</a></div></article>`;}).join('');}function initializeShareButtons(vehicle){const title=`${vehicle.year}${vehicle.make}${vehicle.model}`;const url=window.location.href;const shareText=`Check out this ${title}at Premium Auto Sales!`;const fbBtn=document.getElementById('share-facebook');if(fbBtn){fbBtn.addEventListener('click',()=>{const fbUrl=`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`;window.open(fbUrl,'_blank','noopener,noreferrer,width=600,height=400');});}const twBtn=document.getElementById('share-twitter');if(twBtn){twBtn.addEventListener('click',()=>{const twUrl=`https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}&url=${encodeURIComponent(url)}`;window.open(twUrl,'_blank','noopener,noreferrer,width=600,height=400');});}const emailBtn=document.getElementById('share-email');if(emailBtn){emailBtn.addEventListener('click',async()=>{if(navigator.share){try{await navigator.share({title,text:shareText,url});return;}catch(err){if(err.name==='AbortError')return;}}const subject=encodeURIComponent(`Check out this ${title}`);const body=encodeURIComponent(`${shareText}\n${url}`);window.location.href=`mailto:?subject=${subject}&body=${body}`;});}}function showError(){const loading=document.getElementById('vehicle-loading');const content=document.getElementById('vehicle-detail-content');const error=document.getElementById('vehicle-error');if(loading)loading.hidden=true;if(content)content.hidden=true;if(error)error.hidden=false;document.title='Vehicle Not Found|Premium Auto Sales';}async function init(){const vehicleId=getVehicleIdFromURL();if(!vehicleId||!isValidVehicleId(vehicleId)){showError();return;}try{const vehicle=await fetchVehicleData(vehicleId);if(!vehicle){showError();return;}renderVehicleDetails(vehicle);if(vehicle.images&&vehicle.images.length>0){initializeGallery(vehicle.images);}initializeShareButtons(vehicle);const loading=document.getElementById('vehicle-loading');const content=document.getElementById('vehicle-detail-content');if(loading)loading.hidden=true;if(content)content.hidden=false;const related=await fetchRelatedVehicles(vehicle);renderRelatedVehicles(related);}catch(err){console.error('Error loading vehicle details:',err);showError();}}document.addEventListener('DOMContentLoaded',()=>{init();const closeBtn=document.getElementById('lightbox-close');if(closeBtn){closeBtn.addEventListener('click',closeLightbox);}const prevBtn=document.getElementById('lightbox-prev');if(prevBtn){prevBtn.addEventListener('click',()=>navigateLightbox(-1));}const nextBtn=document.getElementById('lightbox-next');if(nextBtn){nextBtn.addEventListener('click',()=>navigateLightbox(1));}document.addEventListener('keydown',(e)=>{const lightbox=document.getElementById('lightbox');if(!lightbox||lightbox.hidden)return;switch(e.key){case 'Escape':closeLightbox();break;case 'ArrowLeft':navigateLightbox(-1);break;case 'ArrowRight':navigateLightbox(1);break;}});const lightbox=document.getElementById('lightbox');if(lightbox){lightbox.addEventListener('click',(e)=>{if(e.target===lightbox){closeLightbox();}});}});